CREATE TABLE ventas(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,cliente jsonb NOT NULL,fecha timestamptz NOT NULL,metodo_pago varchar(255) NOT NULL CHECK(metodo_pago IN ('EFECTIVO','TARJETA','TRANSFERENCIA','NEQUI','DAVIPLATA')),total numeric(16,2) NOT NULL CHECK(total>=0),estado varchar(255) NOT NULL CHECK(estado IN ('PENDIENTE','CONFIRMADA','RECHAZADA')),clave varchar(255) NOT NULL UNIQUE,solicitud text NOT NULL);
CREATE TABLE detalles(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,venta_id bigint NOT NULL REFERENCES ventas(id),cantidad integer NOT NULL CHECK(cantidad>0),precio numeric(14,2) NOT NULL CHECK(precio>=0),subtotal numeric(16,2) NOT NULL CHECK(subtotal>=0),producto jsonb NOT NULL);CREATE INDEX detalles_venta_idx ON detalles(venta_id);CREATE INDEX ventas_estado_idx ON ventas(estado);